       echoesSecretInLogs: false,
     });
   });
+
+  it('validates dynamic definitions against each call schema and caches validators', async () => {
+    const registry = new ToolRegistry();
+    let citySchemaReads = 0;
+    const citySchema: Record<string, unknown> = {
+      type: 'object',
+      get properties() {
+        citySchemaReads += 1;
+        return {city: {type: 'string'}};
+      },
+      required: ['city'],
+    };
+    const countrySchema: Record<string, unknown> = {
+      type: 'object',
+      properties: {country: {type: 'string'}},
+      required: ['country'],
+    };
+    let activeSchema = citySchema;
+    const seenInputs: Array<Record<string, unknown>> = [];
+
+    registry.register(
+      () => ({
+        name: 'locate',
+        description: 'Resolve location dynamically',
+        inputSchema: activeSchema,
+      }),
+      async input => {
+        seenInputs.push(input);
+        return 'ok';
+      }
+    );
+
+    const readsCounts: number[] = [citySchemaReads];
+    const firstRejection = await registry.execute('locate', {country: 'NL'});
+    readsCounts.push(citySchemaReads);
+
+    activeSchema = countrySchema;
+    const secondRejection = await registry.execute('locate', {city: 'Amsterdam'});
+    const secondPass = await registry.execute('locate', {country: 'NL'});
+
+    activeSchema = citySchema;
+    const cachedPass = await registry.execute('locate', {city: 'Amsterdam'});
+    readsCounts.push(citySchemaReads);
+
+    expect({
+      readsAtRegister: readsCounts[0],
+      compiledOnFirstExecute: (readsCounts[1] ?? 0) > 0,
+      reusedCachedValidator: readsCounts[2] === readsCounts[1],
+      firstRejectedCity: firstRejection.result.includes('city'),
+      secondRejectedCountry: secondRejection.result.includes('country'),
+      secondPassResult: secondPass.result,
+      cachedPassResult: cachedPass.result,
+      seenInputs,
+    }).toEqual({
+      readsAtRegister: 0,
+      compiledOnFirstExecute: true,
+      reusedCachedValidator: true,
+      firstRejectedCity: true,
+      secondRejectedCountry: true,
+      secondPassResult: 'ok',
+      cachedPassResult: 'ok',
+      seenInputs: [{country: 'NL'}, {city: 'Amsterdam'}],
+    });
+  });
 });
